SELECT id, target_type, target_id, author_id, review_round, action, source, operator_id,
       reason, reason_code, create_time, update_time
FROM content_review
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
ORDER BY review_round ASC, id ASC

SELECT id, target_type, target_id, author_id, review_round, action, source, operator_id,
       reason, reason_code, create_time, update_time
FROM content_review
WHERE author_id = #{authorId}
ORDER BY id DESC
LIMIT #{limit}

SELECT cr.target_id AS targetId, cr.reason FROM content_review cr JOIN ( SELECT target_id, MAX(id) AS max_id FROM content_review WHERE target_type = #{targetType} AND action = 'REJECT' AND target_id IN
#{id}
GROUP BY target_id ) latest ON latest.max_id = cr.id

